def fetch_checked(path, info):
    if not path.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        with urllib.request.urlopen(urllib.request.Request(info['url'], headers={'User-Agent':'aboutils archive research/1.0'}), timeout=90) as r:
            content = r.read()
        if hashlib.sha256(content).hexdigest() != info['sha256']:
            raise ValueError(f'checksum mismatch for downloaded {path}')
        path.write_bytes(content)
    content = path.read_bytes()
    if hashlib.sha256(content).hexdigest() != info['sha256']:
        raise ValueError(f'checksum mismatch for {path}')
    return content

def dumps(obj):
    return json.dumps(obj, separators=(',', ':'), ensure_ascii=False, allow_nan=False).encode()

def gz(path, obj):
    path.write_bytes(gzip.compress(dumps(obj), compresslevel=9, mtime=0))

def storms_from(content):
    rows = iter(csv.reader(io.StringIO(content.decode('ascii'))))
    for row in rows:
        if not row or not re.fullmatch(r'(AL|EP|CP)\d{6}', row[0].strip()):
            continue
        sid, name, count = row[0].strip(), row[1].strip(), int(row[2])
        pts, hurricane = [], False
        for _ in range(count):
            r = [v.strip() for v in next(rows)]
            def coord(v): return float(v[:-1]) * (-1 if v[-1] in 'SW' else 1)
            wind = int(r[6]); wind = None if wind == -999 else wind
            pts.append({'time':f'{r[0][:4]}-{r[0][4:6]}-{r[0][6:]}T{r[1][:2]}:{r[1][2:]}Z','lat':coord(r[4]),'lon':coord(r[5]),'wind':wind})
            hurricane |= r[3] == 'HU'
        if hurricane:
            if any(a['time'] > b['time'] for a,b in zip(pts,pts[1:])): raise ValueError('unsorted '+sid)
            yield sid, name, pts

def shape_geometry(shape):
    # Read raw SHP parts rather than pyshp's orientation-dependent GeoJSON.
    parts = list(shape.parts) + [len(shape.points)]
    rings = []
    for a, b in zip(parts,parts[1:]):
        coords = [[float(x),float(y)] for x,y,*_ in shape.points[a:b]]
        if len(coords) < 4 or coords[0] != coords[-1]: raise ValueError('unclosed or short ring')
        # Unwrap consecutive vertices to a continuous longitude plane.
        for i in range(1,len(coords)):
            while coords[i][0]-coords[i-1][0] > 180: coords[i][0] -= 360
            while coords[i][0]-coords[i-1][0] < -180: coords[i][0] += 360
        if coords[-1] != coords[0]: raise ValueError('ring winds around globe')
        # Normalize equivalent longitudes before determining containment.
        shift = 360 * math.floor((sum(p[0] for p in coords[:-1]) / (len(coords)-1) + 180)/360)
        coords = [[x-shift,y] for x,y in coords]
        p = Polygon(coords)
        if not p.is_valid or p.is_empty or p.area == 0: raise ValueError('invalid source ring: '+explain_validity(p))
        rings.append(p)
    # Determine strict parent by geometry, not by winding; align by multiples of 360.
    parents = [None]*len(rings)
    for i, p in enumerate(rings):
        options=[]
        for j,q in enumerate(rings):
            if i == j or q.area <= p.area: continue
            for shift in (0,-360,360):
                candidate=affinity.translate(p,xoff=shift)
                if q.contains(candidate): options.append((q.area,j,shift)); break
        if options: parents[i]=min(options)[1:]
    def depth(i):
        n=0; seen=set()
        while parents[i] is not None:
            if i in seen: raise ValueError('cyclic rings')
            seen.add(i); i=parents[i][0]; n+=1
        return n
    polygons=[]
    for i,p in enumerate(rings):
        if depth(i)%2: continue
        holes=[]
        for j,q in enumerate(rings):
            if parents[j] is not None and parents[j][0] == i and depth(j)%2:
                holes.append(list(affinity.translate(q,xoff=parents[j][1]).exterior.coords))
        poly=Polygon(p.exterior.coords,holes)
        if not poly.is_valid: raise ValueError('invalid source polygon: '+explain_validity(poly))
        # Cut at the dateline; clipping preserves topology, unlike wrapping vertices.
        for k in range(math.floor((poly.bounds[0]+180)/360), math.floor((poly.bounds[2]+180)/360)+1):
            piece=poly.intersection(box(-180+360*k,-90,180+360*k,90))
            if piece.is_empty: continue
            if piece.geom_type == 'Polygon': pieces=[piece]
            elif piece.geom_type == 'MultiPolygon': pieces=list(piece.geoms)
            else: raise ValueError('non-polygon dateline intersection')
            polygons.extend(affinity.translate(x,xoff=-360*k) for x in pieces if x.area > 0)
    geom=MultiPolygon(polygons) if len(polygons)>1 else polygons[0]
    if not geom.is_valid: raise ValueError('invalid assembled geometry: '+explain_validity(geom))
    if abs(geom.area - sum((p.area if depth(i)%2 == 0 else -p.area) for i,p in enumerate(rings))) > max(1e-8,geom.area*1e-9):
        raise ValueError('area mismatch after assembly')
    return mapping(geom)

def convert(content, sid):
    with zipfile.ZipFile(io.BytesIO(content)) as z:
        stems=[x[:-4] for x in z.namelist() if x.lower().endswith('_windswath.shp')]
        if not stems: return None
        if len(stems)!=1: raise ValueError('multiple swath layers')
        stem=stems[0]
        reader=shapefile.Reader(shp=io.BytesIO(z.read(stem+'.shp')),shx=io.BytesIO(z.read(stem+'.shx')),dbf=io.BytesIO(z.read(stem+'.dbf')),encoding='latin1')
        fields=[x[0] for x in reader.fields[1:]]; features=[]
        for sr in reader.iterShapeRecords():
            props=dict(zip(fields,sr.record))
            if str(props.get('STORMID','')).upper() != sid: raise ValueError('storm ID mismatch')
            if props.get('RADII') not in (34,50,64): raise ValueError('unknown wind threshold')
            features.append({'type':'Feature','properties':props,'geometry':shape_geometry(sr.shape)})
        return {'type':'FeatureCollection','features':features} if features else None

def compare_gdal(path, sid, swath):
    # Independent GDAL read from the original ZIP, not from pyshp output.
    with fiona.Env(OGR_ORGANIZE_POLYGONS='DEFAULT'):
        with fiona.open('zip://' + str(path.resolve()), layer=sid+'_windswath') as src:
            original = [read_geometry(f['geometry']) for f in src]
    emitted = [read_geometry(f['geometry']) for f in swath['features']]
    if len(original) != len(emitted) or any(not g.is_valid for g in original):
        raise ValueError('GDAL geometry invalid or feature count mismatch')
    for a, b in zip(original, emitted):
        if a.symmetric_difference(b).area > 1e-8:
            raise ValueError('GDAL symmetric difference exceeds tolerance')

def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--cache',type=Path,required=True); args=parser.parse_args()
    out=ROOT/'public/data/storms'; (out/'swaths').mkdir(parents=True,exist_ok=True)
    allstorms=[]
    for name,info in INPUTS['hurdat'].items(): allstorms.extend(storms_from(fetch_checked(args.cache/name,info)))
    allstorms.sort(key=lambda x:(-int(x[0][4:]),x[0])); catalog=[]; tracks={}; failures={}
    for sid,name,pts in allstorms:
        tracks[sid]=pts; swath=None
        if sid in INPUTS['zips']:
            # Download/checksum failures are fatal, not mistaken for missing swaths.
            raw=fetch_checked(args.cache/'zips'/f'{sid}.zip',INPUTS['zips'][sid])
            try:
                swath=convert(raw,sid)
                if swath: compare_gdal(args.cache/'zips'/f'{sid}.zip',sid,swath)
            except Exception as e:
                swath=None
                failures[sid]=str(e)
        target=out/'swaths'/f'{sid}.bin'
        if swath: gz(target,swath)
        elif target.exists(): target.unlink()
        winds=[p['wind'] for p in pts if p['wind'] is not None]
        catalog.append({'id':sid,'name':name,'year':int(sid[4:]),'basin':sid[:2],'start':pts[0]['time'],'end':pts[-1]['time'],'peakWindKt':max(winds) if winds else None,'hasSwath':bool(swath)})
    gz(out/'tracks.bin',tracks)
    (out/'catalog.json').write_bytes(dumps({'storms':catalog,'throughYear':2025})+b'\n')
    print(json.dumps({'storms':len(catalog),'swaths':sum(s['hasSwath'] for s in catalog),'failures':failures},indent=2))
if __name__=='__main__': main()
